def simulate_spread(initial_state):
    """
    Simulates the bacterial spread on a 4x4 grid.
    Rules:
    1) 2x2 with 3 infected -> sterile cell becomes infected.
    2) 2x2 with 2 infected -> all 4 cells flip state.
    """
    grid = initial_state.copy()
    max_steps = 100  # Safety break

    for step in range(max_steps):
        current_grid = grid.copy()
        next_grid = grid.copy()
        changed = False

        # Apply Rule 2 (Mutation/Flip) first, as it's a global change on the 2x2 block
        # Iterate over all possible 2x2 top-left corners (0,0) to (2,2)
        for r in range(3):
            for c in range(3):
                subgrid = current_grid[r:r+2, c:c+2]
                count = np.sum(subgrid)

                if count == 2:
                    # Rule 2: Flip all 4 cells in next_grid
                    # Note: This overrides any state in next_grid from the start of the step
                    next_grid[r:r+2, c:c+2] = 1 - next_grid[r:r+2, c:c+2]

