def apply_rules(grid):
    """Applies Rule 1 and Rule 2 simultaneously to determine the next state."""
    new_grid = grid.copy()
    changes = {} # Store changes to avoid propagating within one step

    # Iterate over all possible 2x2 squares
    for r in range(N - 1):
        for c in range(N - 1):
            subgrid = grid[r:r+2, c:c+2]
            infected_count = np.sum(subgrid)

            # Rule 1: 3/4 infected -> spread
